dtsPropsFor.Form:
/** Field definitions keyed by field name — the schema drives what renders. */
  form: Record<string, any>;
  /** Form identity; also namespaces the rendered field ids. */
  name: string;
  /** Seed values, keyed by field name. Omit for an empty form. */
  initialValues?: Record<string, any>;
  /** Fires on every edit with the form name and the current values. */
  onChange?: (name: string, values: any) => void;
  /** Per-field prop overrides, keyed by field name — for props a static schema can't know (live option lists etc). */
  fieldProps?: { [key: string]: any };
  /** Value converters applied at submit time, keyed by field type. */
  converters?: any;

dtsPropsFor.ThumbnailCard:
title: string;
  /** Rendered before the truncated title text, e.g. a colored type badge. */
  titlePrefix?: React.ReactNode;
  /** Header-right content, typically a row of IconButtons. */
  actions?: React.ReactNode;
  /** Renders a background image, fit per `fit`. Ignored if children is set. */
  thumbnailUrl?: string;
  /** 'cover' (default) crops to fill; 'contain' letterboxes and never crops. */
  fit?: 'cover' | 'contain';
  width?: number;
  thumbnailHeight?: number;
  children?: React.ReactNode;

dtsPropsFor.List:
/** Rows to render. */
  items: Array<any>;
  /** Column definitions keyed by field name (DisplaySchema). */
  schema: Record<string, any>;
  /** List identity; also the default persistence key. */
  name: string;
  onSelect?: (values: any) => void;
  pageSize?: number;
  csvHeaders?: Array<{ label: string; key: string }>;
  /** Opts in to a "Columns" picker letting the user hide/show columns. Off by default. */
  columnSelectable?: boolean;

dtsPropsFor.ListControls:
visibleCount: number;
  totalCount: number;
  pickableKeys: string[];
  columnSelectSchema: Record<string, any>;
  initialValues: Record<string, boolean>;
  onColumnsChange: (hidden: Set<string>) => void;
  columnSelectable?: boolean;
  /** Undefined = the schema didn't declare buttons.add, so nothing renders. */
  onAdd?: () => void;
  /** Caller-defined toolbar actions that don't fit the add/columns shape. */
  customButtons?: Array<any>;

dtsPropsFor.Prompt:
isOpen: boolean;
  message: any;
  toggle: (response: boolean) => void;

dtsPropsFor.Fabric:
/** per-form's field renderer (passed as FormWrapper's `Template`). One switch
   * over `type` covering every field kind; unmatched types fall back to a TextField.
   * Rarely rendered directly — Form wires it for you. */
  type: string;
  label?: string;
  name: string;
  value: any;
  onChange: (name: string, value: any) => void;
  onFocus?: (name: string) => void;
  errors?: string[];
  dirty?: boolean;
  touched?: boolean;
  parent?: any;
  [key: string]: unknown;

dtsPropsFor.ButtonDropdown:
/** Button label. */
  value: any;
  /** Menu entries; each item's `value` becomes its text. */
  menuActions: Array<{ value: string; [key: string]: any }>;
  /** 'primary' renders a PrimaryButton, anything else a DefaultButton. */
  color?: string;
  [key: string]: unknown;

dtsPropsFor.Splashscreen:
/** Logo component rendered centred while the app loads. */
  Icon: React.FC<any>;
  /** Shown below the logo once the initial load has actually failed —
   * not during the normal brief first fetch. Empty renders nothing. */
  statusText?: string;

dtsPropsFor.Photo:
/** Image source rendered in the preview. */
  image?: string;
  base64URL?: string | null;
  /** Enables the crop UI. */
  cropping?: boolean;
  previewDimensions?: { height: number; width: number };
  fileDimensions?: Record<string, any>;
  icon?: string;
  selected?: boolean;
  error?: any;
  [key: string]: unknown;

dtsPropsFor.Logo:
style?: any;
  className?: any;
  onClick?: any;

dtsPropsFor.Header:
/** The current user/settings payload (`my`) that drives nav and settings. */
  my: any;
  Brand?: React.FC<any>;
  Controls?: React.FC<any>;
  ExternalApps?: React.FC<any>;

dtsPropsFor.HeaderLink:
to: any;
  children: any;
  className?: string;
  active?: boolean;

dtsPropsFor.ReactiveAdmin:
/** gql documents per slot: list, show, and optionally new/edit/delete/subscribe.
   * Each slot's presence gates real behaviour, not just which mutation fires. */
  dispatcher: any;
  /** Singular/plural display names for the record type. */
  name: any;
  /** Field definitions for list/show/edit/new (ITASchema). */
  schemaDefinition: any;
  /** Override individual slots (list/new/show/edit); omitted slots keep the
   * Fluent defaults. Caller overrides always win. */
  components?: any;
  callBacks?: any;
  pageSize?: number;

dtsPropsFor.ListScreen:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  pageSize?: number;
  components?: any;
  /** Overrides the query's result field — defaults to `get${name.plural}`. */
  queryResultKey?: string;
  /** Suppresses the built-in heading + Links row, for embedding. */
  hideHeader?: boolean;

dtsPropsFor.Create:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  callBacks?: any;
  components?: any;

dtsPropsFor.Update:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  callBacks?: any;
  components?: any;

dtsPropsFor.Show:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  callBacks?: any;
  components?: any;

dtsPropsFor.Delete:
dispatcher: any;
  id: any;
  name: any;
  callBacks?: any;

dtsPropsFor.CardList:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  /** Schema key rendered as each card's title. */
  titleField: string;
  /** Schema key holding an image URL for the thumbnail. Omit for text-only cards. */
  thumbnailField?: string;
  cardWidth?: number;
  components?: any;
  pageSize?: number;

dtsPropsFor.SwitchableList:
dispatcher: any;
  name: any;
  schemaDefinition: any;
  /** Card-view title field (card view only). */
  titleField: string;
  thumbnailField?: string;
  cardWidth?: number;
  thumbnailHeight?: number;
  thumbnailFit?: 'cover' | 'contain';
  defaultView?: string;
  components?: any;
  pageSize?: number;

dtsPropsFor.Denim:
/** Theme map keyed by theme name; each entry is a (fontSize) => theme factory. */
  themes: any;
  /** Component registry keyed by an application's `frontEnd` value. */
  components?: any;
  /** Rendered at the root route when no launch page is configured. */
  RootComponent?: any;
  Logo?: React.FC<any>;
  Brand?: React.FC<any>;
  Controls?: React.FC<any>;
  ExternalApps?: React.FC<any>;
